where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
and BASE_SUBJECT_NATURE = #{baseSubjectNature,jdbcType=VARCHAR}
and BOK_DETAIL_ID = #{bokDetailId,jdbcType=VARCHAR}

mapper.delete:
delete from BOK_SUBJECT_DETAIL
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and BASE_SUBJECT_NATURE = #{baseSubjectNature,jdbcType=VARCHAR}
  and BOK_DETAIL_ID = #{bokDetailId,jdbcType=VARCHAR}

mapper.update:
update BOK_SUBJECT_DETAIL
set SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR},
    DETAIL_SUBJECT_NO = #{detailSubjectNo,jdbcType=VARCHAR},
    DETAIL_SUBJECT_NO_TAIL = #{detailSubjectNoTail,jdbcType=VARCHAR},
    ACC_INT_FLAG = #{accIntFlag,jdbcType=VARCHAR},
    OVERDRAWN_FLAG = #{overdrawnFlag,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and BASE_SUBJECT_NATURE = #{baseSubjectNature,jdbcType=VARCHAR}
  and BOK_DETAIL_ID = #{bokDetailId,jdbcType=VARCHAR}
